def minPath(grid, k):
    N = len(grid)
    visited = [[False] * N for _ in range(N)]
    paths = []

    def dfs(x, y, path):
        if len(path) == k:
            paths.append(path + [grid[x][y]])
            return
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                visited[nx][ny] = True
                dfs(nx, ny, path + [grid[x][y]])
                visited[nx][ny] = False

    for i in range(N):
        for j in range(N):
            if not visited[i][j]:
                dfs(i, j, [])

    min_path = min(paths, key=lambda path: (path, path.index(min(path))))
    return min_path

